import{_ as l,C as s,o as d,c as i,j as t,a as o,b as c,w as r,E as n,a3 as h,a2 as p}from"./chunks/framework.C9XHwBqm.js";const v=JSON.parse('{"title":"How the APIs are built","description":"","frontmatter":{},"headers":[],"relativePath":"guide/apis.md","filePath":"guide/apis.md","lastUpdated":1795642929000}'),u={name:"guide/apis.md"};function g(m,e,b,P,y,_){const a=s("Mermaid");return d(),i("div",null,[e[1]||(e[1]=t("h1",{id:"how-the-apis-are-built",tabindex:"-1"},[o("How the APIs are built "),t("a",{class:"header-anchor",href:"#how-the-apis-are-built","aria-label":'Permalink to "How the APIs are built"'},"​")],-1)),e[2]||(e[2]=t("p",null,[o("There is no Express, FastAPI, or Flask app for the chat stack. Three "),t("strong",null,"hand-rolled"),o(" HTTP layers sit behind the same-origin proxy.")],-1)),(d(),c(h,null,{default:r(()=>[n(a,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20TB%0A%20%20page%5B%22React%20page%3Cbr%2F%3Eweb%2F%22%5D%0A%20%20proxy%5B%22Vite%20or%20chat_server.py%3Cbr%2F%3Esame-origin%20proxy%22%5D%0A%20%20model%5B%22Model%20API%20%3A8080%3Cbr%2F%3EC%20lm-serve%20or%20llama-server%22%5D%0A%20%20tools%5B%22Tools%20API%20%3A8081%2F%3A8082%3Cbr%2F%3EPython%20chat_tools.py%22%5D%0A%0A%20%20page%20--%3E%20proxy%0A%20%20proxy%20--%3E%7C%22%2Fv1%20%2Fhealth%22%7C%20model%0A%20%20proxy%20--%3E%7C%22%2Ftools*%22%7C%20tools%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=p('<h2 id="_1-model-api-8080" tabindex="-1">1. Model API (<code>:8080</code>) <a class="header-anchor" href="#_1-model-api-8080" aria-label="Permalink to &quot;1. Model API (`:8080`)&quot;">​</a></h2><ul><li><strong>Engines:</strong> <code>bin/lm-serve</code> (C, Kevin’s engine) or <strong>llama-server</strong> (llama.cpp) for GGUFs the C engine does not load.</li><li><strong>Shape:</strong> OpenAI-compatible — <code>/v1/chat/completions</code>, <code>/v1/models</code>, <code>/health</code>.</li><li><strong>On the Mac:</strong> SSH tunnel <code>ssh -N -L 8080:127.0.0.1:8080 toor@…</code> — leave this up when restarting the UI.</li></ul><h2 id="_2-tools-api-8081-remote-8082-local" tabindex="-1">2. Tools API (<code>:8081</code> remote, <code>:8082</code> local) <a class="header-anchor" href="#_2-tools-api-8081-remote-8082-local" aria-label="Permalink to &quot;2. Tools API (`:8081` remote, `:8082` local)&quot;">​</a></h2><ul><li><strong>Implementation:</strong> <code>tools/chat_tools.py</code> — Python 3 <strong>stdlib only</strong> (<code>ThreadingHTTPServer</code> + <code>BaseHTTPRequestHandler</code>).</li><li><strong>JSON routes</strong> (all under <code>/tools/</code>):</li></ul><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Role</th></tr></thead><tbody><tr><td>GET</td><td><code>/tools/status</code></td><td>Servers, catalog, limits</td></tr><tr><td>GET</td><td><code>/tools/projects</code></td><td>Owner-registered projects</td></tr><tr><td>GET</td><td><code>/tools/servers/&lt;id&gt;/tools</code></td><td>List tools (may start the MCP server)</td></tr><tr><td>POST</td><td><code>/tools/servers/&lt;id&gt;/call</code></td><td>Call a tool</td></tr><tr><td>POST</td><td><code>/tools/servers/&lt;id&gt;/stop</code></td><td>Stop a server</td></tr><tr><td>POST</td><td><code>/tools/catalog/&lt;id&gt;/add</code></td><td>Add a catalog entry to config</td></tr><tr><td>POST</td><td><code>/tools/search</code></td><td>SearXNG web search</td></tr></tbody></table><p>Projects and git helpers live in sibling modules (<code>chat_projects.py</code>, <code>chat_git.py</code>, …) and are registered as a native <code>&quot;project&quot;</code> server. The model never receives a free-form shell or token.</p><h2 id="_3-proxy-layer" tabindex="-1">3. Proxy layer <a class="header-anchor" href="#_3-proxy-layer" aria-label="Permalink to &quot;3. Proxy layer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Proxy</th><th>Built with</th><th>Forwards</th></tr></thead><tbody><tr><td>Vite (<code>web/vite.config.ts</code>)</td><td>Node</td><td><code>/v1</code>, <code>/health</code>, <code>/tools</code>, <code>/tools-local</code></td></tr><tr><td><code>tools/chat_server.py</code></td><td>Python stdlib</td><td>Same paths (+ static <code>web/dist</code>)</td></tr></tbody></table><p>Environment defaults:</p><ul><li><code>LM_SERVE_URL</code> → <code>http://127.0.0.1:8080</code></li><li><code>LM_TOOLS_URL</code> → <code>http://127.0.0.1:8081</code></li><li><code>LM_TOOLS_LOCAL_URL</code> → <code>http://127.0.0.1:8082</code></li></ul><h2 id="security-posture-api" tabindex="-1">Security posture (API) <a class="header-anchor" href="#security-posture-api" aria-label="Permalink to &quot;Security posture (API)&quot;">​</a></h2><ul><li>Listen on <strong>127.0.0.1</strong> by default.</li><li>Non-loopback bind requires <code>CHAT_PASSWORD</code> (HTTP Basic).</li><li>Tool POSTs need JSON + loopback Origin (or none); CSP stays <code>&#39;self&#39;</code>.</li><li>Secrets (e.g. GitHub token) live in <code>~/.config/kevin-ai/tool-service.env</code> mode <code>600</code>, never in the repo.</li></ul>',12))])}const A=l(u,[["render",g]]);export{v as __pageData,A as default};
